#!/usr/bin/env python3
"""Generate only competition/*.html; all source links are claim-specific."""
from __future__ import annotations
import html
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
BASE = "7c2f5459350c8a94f13cd12d4315ba92b044275a"
REPO = "https://github.com/sassnarep3-star/Own8"
SITE = "https://sassnarep3-star.github.io/Own8/competition/"


def load(p): return json.loads((ROOT / p).read_text())
def esc(v): return html.escape(str(v), quote=True)
class H(str): pass

def tag(text, color="amber"):
    return H(f'<span class="tag {esc(color)}">{esc(text)}</span>')

def value(v, digits=1, signed=False, percent=False):
    if v is None: return None
    n = v * 100 if percent else v
    return f'{n:{"+" if signed else ""}.{digits}f}' + ("%" if percent else "")

SOURCES = {s["id"]: s for s in load("data/sources.json")["sources"]}
SHORT = {"NFL-STANDINGS":"Standings","NFL-SCHEDULE":"Schedule","NFL-SCORES":"Scores","NFL-INJURIES":"Injuries","NFL-NGS":"NFL NGS","DK-LINES":"Operator","DK-ODDS":"Odds guide","DK-FOOTBALL":"Market guide","DK-PARLAY":"Parlay guide","DK-PROPS":"Prop source","SCIPY-R":"SciPy r","SCIPY-BOOT":"SciPy CI","NIST-CI":"NIST CI","NIST-BOOT":"NIST bootstrap","NIST-TIME":"NIST time","SM-HOLM":"Holm docs","WA-RULES":"WA regulator","NCPG-HELP":"NCPG"}


def refs(ids):
    if not ids: raise ValueError("Every table row requires an official reference")
    links = []
    for ident in ids:
        s = SOURCES[ident]
        cls = ' class="operator"' if ident.startswith("DK-") else ""
        links.append(f'<a{cls} href="{esc(s["url"])}" target="_blank" rel="noopener noreferrer" title="{esc(s["publisher"] + ": " + s["title"])}">{esc(SHORT[ident])} ↗</a>')
    return H('<span class="source-links">' + "".join(links) + "</span>")


def table(ident, title, headers, rows, caption="", download=None):
    body = []
    for values, sources in rows:
        cells = []
        for v in values:
            if v is None:
                cells.append('<td class="missing" aria-label="Unverified or not available"></td>')
            else:
                cells.append('<td>' + (str(v) if isinstance(v, H) else esc(v)) + '</td>')
        source_html = sources if isinstance(sources, H) else refs(sources)
        body.append('<tr>' + "".join(cells) + '<td>' + source_html + '</td></tr>')
    headings = "".join(f'<th scope="col"><button type="button" data-column="{i}" aria-label="Sort by {esc(h)}">{esc(h)}</button></th>' for i, h in enumerate(headers)) + '<th scope="col">Official reference</th>'
    down = f'<a class="table-download" href="{esc(download)}" download>Download data ↓</a>' if download else '<span>Blank cells = unavailable / unverified</span>'
    return f'''<section class="table-card" id="{esc(ident)}">
<div class="table-tools"><div class="table-title">{esc(title)}<small>{len(rows)} rows · source-linked · checked 04 Nov 2026</small></div><label class="table-search"><span class="visually-hidden">Filter {esc(title)}</span><input type="search" placeholder="Filter this table…" aria-controls="table-{esc(ident)}"></label></div>
<div class="table-wrap" tabindex="0" role="region" aria-label="{esc(title)}"><table id="table-{esc(ident)}"><caption>{esc(caption)}</caption><thead><tr>{headings}</tr></thead><tbody>{"".join(body)}</tbody></table></div>
<div class="table-empty" role="status">No rows match your filter.</div><div class="table-footer"><span class="row-count" aria-live="polite">{len(rows)} of {len(rows)} rows</span>{down}</div></section>'''

NAV = [
 ("WORKSPACE",[("index.html","Overview","◫"),("executive-summary.html","Executive summary","≡")]),
 ("RESEARCH",[("singles.html","Single bets","↗"),("parlays.html","Parlays","⋈"),("player-props.html","Player prop combos","⊕"),("correlations.html","Correlations","⌁")]),
 ("COMPETITION",[("leaderboard.html","Leaderboard","▥"),("validation.html","Validation gates","◇"),("evidence.html","NFL evidence","▤")]),
 ("ASSURANCE",[("flagged.html","Flagged for Review","⚑"),("coverage.html","Entry-by-entry audit","☷"),("repo-review.html","Repository review","⌘"),("sources.html","Source register","↗")])]


def icon(mark):
    paths = {
        "◫": '<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',
        "≡": '<path d="M5 6h14M5 12h14M5 18h9"/>',
        "↗": '<path d="m4 17 6-6 4 3 6-8M14 6h6v6"/>',
        "⋈": '<circle cx="7" cy="9" r="4"/><circle cx="17" cy="15" r="4"/><path d="m10 11 4 3"/>',
        "⊕": '<circle cx="12" cy="8" r="4"/><path d="M5 21v-2a7 7 0 0 1 14 0v2M18 4h4m-2-2v4"/>',
        "⌁": '<path d="m3 17 4-8 5 5 4-9 5 8"/><circle cx="7" cy="9" r="1"/><circle cx="16" cy="5" r="1"/>',
        "▥": '<path d="M4 21V10h4v11M10 21V4h4v17M16 21V8h4v13"/>',
        "◇": '<path d="m12 2 8 4v6c0 5-8 10-8 10S4 17 4 12V6zM8 11l3 3 5-6"/>',
        "▤": '<rect x="5" y="3" width="14" height="18" rx="2"/><path d="M8 7h8M8 12h8M8 17h5"/>',
        "⚑": '<path d="M5 21V3h14l-3 5 3 5H5"/>',
        "☷": '<path d="M9 5h12M9 12h12M9 19h12M3 5h1M3 12h1M3 19h1"/>',
        "⌘": '<path d="m8 6-6 6 6 6m8-12 6 6-6 6M14 3l-4 18"/>'
    }
    return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' + paths[mark] + '</svg>'


def page(name, title, subtitle, body, number="01"):
    nav = ""
    for group, items in NAV:
        nav += f'<div class="nav-group">{group}</div>'
        for href, label, mark in items:
            current = ' class="active" aria-current="page"' if name == href else ""
            count = '<span class="nav-count">16</span>' if href == "flagged.html" else ""
            nav += f'<a href="{href}"{current}><span class="nav-mark" aria-hidden="true">{icon(mark)}</span>{label}{count}</a>'
    text = f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light"><title>{esc(title)} · Own8 Competition</title><meta name="description" content="Source-linked NFL paper research competition. Dated evidence, explicit uncertainty, no invented performance and no real-money wagers."><link rel="canonical" href="{SITE + name}"><link rel="icon" href="assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="assets/style.css"><script src="assets/app.js" defer></script></head>
<body data-snapshot-date="2026-11-04"><a class="skip" href="#main">Skip to content</a><aside class="sidebar" id="navigation"><a class="brand" href="index.html"><span class="brand-symbol" aria-hidden="true">8</span><span><span class="brand-name">OWN8</span><span class="brand-sub">Competition lab</span></span></a><nav aria-label="Main navigation">{nav}</nav><div class="side-bottom"><div class="side-note"><strong><span class="status-dot"></span>Proof before points.</strong>2026 NFL · Week 9 snapshot<br>Paper research. No live quotes.<br><a href="responsible-research.html" style="color:#aac6b5">Responsible research ↗</a></div></div></aside>
<div class="shell"><header class="topbar"><button class="menu-toggle" type="button" aria-label="Toggle navigation" aria-controls="navigation" aria-expanded="false">{icon("≡")}</button><div class="breadcrumb"><span class="parent">Own8 research</span><span aria-hidden="true">/</span><strong>{esc(title)}</strong></div><div class="topbar-right"><time class="date-label" datetime="2026-11-04">04 NOV 2026 · UTC</time><a class="repo-link" href="{REPO}/tree/main/competition" target="_blank" rel="noopener noreferrer">Repository ↗</a></div></header>
<main id="main"><div class="page-heading"><div><p class="eyebrow">NFL LINE ORIGINATION / PAPER COMPETITION</p><h1>{esc(title)}</h1><p>{esc(subtitle)}</p></div><span class="page-number">OWN8 / {esc(number)}</span></div>{body}</main>
<footer class="footer"><div>Research, not a wagering service. No cash rewards. No claim that luck can be eliminated.<br><span id="snapshot-age">Selected fields checked 04 Nov 2026. This is a dated snapshot, not live betting data.</span></div><div class="footer-links"><a href="sources.html">Sources</a> &nbsp;·&nbsp; <a href="flagged.html">Review flags</a> &nbsp;·&nbsp; <a href="responsible-research.html">Responsible research</a></div></footer></div></body></html>'''
    (ROOT / name).write_text(text)


def section(title, link=None):
    return f'<div class="section-head"><h2>{esc(title)}</h2>' + (f'<a href="{esc(link[0])}">{esc(link[1])} →</a>' if link else "") + '</div>'


def notice(text, kind=""):
    return f'<div class="callout {kind}"><span class="callout-icon" aria-hidden="true">ⓘ</span><div>{text}</div></div>'


def hypothesis_rows(strategies):
    return [([H(f'<strong>{esc(s["id"])}</strong><span class="sub">{esc(s["name"])}</span>'), H(f'<div class="long">{esc(s["hypothesis"])}</div>'), s["target"], H(f'<div class="long">{esc(s["missing"])}</div>'), tag("RESEARCH / HOLD")], s["source_ids"]) for s in strategies]


