    baseline_rows = [([f'{b["away"]} at {b["home"]}',value(b["home_handicap"],2,True),value(b["total"],2),None,None,tag("UNVALIDATED")],b["source_ids"]) for b in baselines]
    page("singles.html","Single bets","Spread, total and moneyline hypotheses. Observed operator prices are never mistaken for our own forecasts.",notice("<strong>Snapshot, not a pick sheet.</strong> Quotes were observed on the primary operator's own page. Individual update instants and exact retrieval times are unconfirmed; current/executable-price status is held.")+'<div class="topic-links"><a href="#prices">Primary price snapshot</a><a href="#baseline">B0 reference lines</a><a href="#single-hypotheses">Research hypotheses</a></div>'+table("prices","Week 9 · primary operator price snapshot",["NFL fixture","NFL kickoff","Home handicap @ odds","Total @ odds","Moneyline @ odds","ML overround†","State"],price_rows,"American odds as rendered by DraftKings. NFL schedule controls the fixture. †Overround is a derived sum of implied probabilities minus one; not expected ROI. Prices are dated observations, not live quotes.","data/evidence/draftkings-2026-week9.csv")+table("baseline","B0 · frozen reference benchmark",["Fixture","Home handicap†","Total†","Our win probability","Validated edge","State"],baseline_rows,"†DERIVED research outputs, not official NFL values or validated fair prices. HFA=0 by benchmark design for every venue; no distribution means no inferred win probability or betting edge.","results/reference-lines.json")+'<div class="formula">away points = (away PF / GP + home PA / GP) / 2\nhome points = (home PF / GP + away PA / GP) / 2\nhome margin = home points − away points\n<em>signed home handicap = −home margin</em>\ncover value = actual home margin + signed home handicap</div>'+table("single-hypotheses","Single-market research catalog",["Hypothesis","Proposed signal","Target","Evidence missing","State"],hypothesis_rows([s for s in catalog if s["category"]=="single"]),"Hypotheses are project proposals; no empirical performance is asserted."),"03")

    parlay_rows = [(["Different games",None,None,None,"No independence assumption",tag("HOLD")],["DK-PARLAY","SCIPY-R","NIST-TIME"]),(["Same game",None,None,None,"Discrete joint outcomes; push/void rules",tag("HOLD")],["DK-PARLAY","SCIPY-R","NFL-SCORES"])]
    page("parlays.html","Parlays","A combined wager is its own contract. Two marginal estimates do not establish a joint price.",notice("<strong>Both parlay lanes are held.</strong> No exact combined quote, matched binary-outcome correlation or independently calibrated joint distribution has been established.")+table("joint","Joint-contract evidence",["Lane","Outcome correlation","Joint win probability","Combined quote","Required treatment","State"],parlay_rows,"Unknowns stay blank, including for different games. Correlation between season totals is not correlation between two selected bet outcomes.")+table("parlay-hypotheses","Parlay research catalog",["Hypothesis","Proposed signal","Target","Evidence missing","State"],hypothesis_rows([s for s in catalog if s["category"]=="parlay"]),"Two-leg maximum is a project policy, not a guarantee of lower risk.")+ '<div class="grid-equal"><div class="card"><h2>Two binary legs only</h2><p>If the same two win indicators and their correlation are actually measured, their joint win probability is:</p><div class="formula">p(A and B) = pA · pB + ρ · √[pA(1−pA)pB(1−pB)]\nmax(0, pA+pB−1) ≤ p(A and B) ≤ min(pA,pB)</div><p>These are identities with valid binary marginals. They do not supply a missing ρ, handle pushes, or identify a three-leg joint distribution.</p>'+refs(["SCIPY-R"])+'</div><div class="card"><h2>Settlement must not be guessed</h2><p>All known winning legs use the exact locked combined quote. A push, void, DNP or unresolved tie is held until market-specific rules and any exact repriced subset quote are verified.</p><p>The engine never multiplies single-leg prices to manufacture an executable same-game payout.</p>'+refs(["DK-PARLAY","DK-FOOTBALL"])+'</div></div>',"04")

    props = load("data/props-unverified.json")
    prop_rows = [([p["game"],p["player"],"Passing yards",None,None,None,tag("PAIRING UNVERIFIED")],["DK-PROPS","NFL-INJURIES"]) for p in props]
